/* { dg-do run } */

enum e1 { A, B };
enum e2 { C, D };

__attribute__((noinline,noclone))
enum e1 f(unsigned int *p)
{
  *(enum e1 *)p = A;
  *(enum e2 *)p = D;
  return *(enum e1 *)p;
}

int main()
{
  unsigned int storage;

  if (f(&storage) != B)
    __builtin_abort();
  return 0;
}

/* { dg-do run } */
/* { dg-additional-options "-fshort-enums" } */

enum e1 { c1 = -__INT_MAX__ };

__attribute__((noinline,noclone))
int f(enum e1 *p, signed int *q)
{
  *p = c1;
  *q = 2;
  return *p;
}

enum e2 { c2 = __SHRT_MAX__ + 1};

__attribute__((noinline,noclone))
int g(enum e2 *p, unsigned short *q)
{
  *p = c2;
  *q = 2;
  return *p;
}

enum e3 { c3 = __SCHAR_MAX__ };

__attribute__((noinline,noclone))
int h(enum e3 *p, unsigned char *q)
{
  *p = c3;
  *q = 2;
  return *p;
}

int main()
{
  signed x;
  unsigned short y;
  unsigned char z;

  if (f(&x, &x) != 2)
    __builtin_abort();
  if (g(&y, &y) != 2)
    __builtin_abort();
  if (h(&z, &z) != 2)
    __builtin_abort();
  return 0;
}

/* { dg-do run } */
/* { dg-additional-options "-fno-short-enums" } */

enum e1 { c1 };

__attribute__((noinline,noclone))
int f(enum e1 *p, unsigned *q)
{
  *p = c1;
  *q = 2;
  return *p;
}

int main()
{
  unsigned x;

  if (f(&x, &x) != 2)
    __builtin_abort();
  return 0;
}
